)

func sample(slug, name string) Entry {
	return Entry{
		Slug: slug, Name: name, Tags: []string{"Java", "spring-boot"},
		Source: Source{Kind: KindGit, URL: "https://github.com/acme/" + slug + ".git", Ref: "main"},
