// showsTree reports whether the tree table is what is on screen, which is what
// decides whether the footer carries a breadcrumb and a filter bar.
func (m Model) showsTree() bool {
	if !m.shared.IsAuthenticated || m.loading || m.error != "" || len(m.nodes) == 0 {
		return false
	}
	if m.creationForm != nil {
		return false
	}
	switch m.mode {
	case ModeNormal, ModeSelecting:
		return true
	default:
		return false
	}
}

// renderTabBar renders the tab bar at the bottom of the viewport
func (m Model) renderTabBar() string {
	tabs := []theme.TabItem{{Label: theme.IconHome + " home"}}
	for _, node := range m.navigationStack {
		if node != nil {
			tabs = append(tabs, theme.TabItem{Label: node.Name})
		}
	}
	if m.currentGroupNode != nil {
		tabs = append(tabs, theme.TabItem{Label: m.currentGroupNode.Name})
	}
	return theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, m.activeTabIndex), m.width)
}

// nodeTypeLabel returns the type label for a tree node, in the forge's own
// words: a GitLab user reads Group/Project, a GitHub user Organization/
// Repository.
func nodeTypeLabel(v forge.Vocabulary, node *TreeNode) string {
	if node.Type == NodeTypeGroup {
		return v.Namespace
	}
	return v.Repository
}

// HeaderView interface implementation

func (m Model) GetShortcuts() shortcut.Shortcuts {
	// Mode-specific shortcuts
	switch m.mode {
	case ModeLoadingTemplates:
		return []shortcut.Shortcut{}
	case ModeSelecting:
		// ←→ keeps drilling here, and that is the point: deselecting inside a
		// ticked group means going into it (decision 10).
		return []shortcut.Shortcut{
			{Key: "space", Description: "Tick or untick"},
			{Key: "←→", Description: "Open/Back"},
			{Key: "enter", Description: "Choose a destination"},
			{Key: "/", Description: "Search"},
			{Key: "esc", Description: "Cancel"},
		}
	case ModeCloning:
		return m.cloningShortcuts()
	case ModeCreatingProject:
		return []shortcut.Shortcut{
			{Key: "↑↓", Description: "Navigate fields"},
			{Key: "←→", Description: "Select option"},
			{Key: "enter", Description: "Submit"},
			{Key: "esc", Description: "Cancel"},
		}
	case ModeConfirmingDelete:
		// ↑↓ is Rule 138 territory — obvious, so not advertised. It replaced
		// tab here when D4 was fixed.
		return []shortcut.Shortcut{
			{Key: "space", Description: "Toggle"},
			{Key: "y/n", Description: "Confirm"},
			{Key: "esc", Description: "Cancel"},
		}
		if len(m.table.Items()) > 0 && m.error == "" {
			// filter bar (when visible) + breadcrumb tab bar + empty line + info line
			return 3 + m.table.FilterBar().ExtraHeight()
		}
	}
	return 2 // empty line + info line
}

// RenderFooter returns the footer content rendered below the viewport (Rule 124).
func (m Model) RenderFooter(width int) string {
	if m.mode == ModeSelecting {
		infoLine := m.footer.View(width, sharedcomponents.Status{Text: m.selectionMessage})
		return m.renderTabBar() + "\n" + theme.EmptyLineBg(width) + "\n" + infoLine
	}
	if m.mode == ModeFuzzyFinding && m.fuzzyFinder != nil {
		infoLine := m.footer.View(width, sharedcomponents.Status{Text: m.fuzzyFinder.StatusText()})
		return m.fuzzyFinder.RenderBar(width) + "\n" + theme.EmptyLineBg(width) + "\n" + infoLine
	}
	if m.mode == ModeNormal && len(m.table.Items()) > 0 && m.error == "" {
		var parts []string
		if bar := m.table.FilterBar(); bar.IsVisible() {
			parts = append(parts, bar.View())
		}
		parts = append(parts, m.renderTabBar(), theme.EmptyLineBg(width), m.renderInfoLine(width))
		return strings.Join(parts, "\n")
	}
	// An empty listing, or one that failed to load, still gets its info line:
	// Rule 124 budgets one whatever it holds, and this branch used to render a
	// second blank line instead — so a footer message posted here was
	// swallowed. That is exactly where a refusal lands (Y on an empty listing
	// has nothing to copy), and a refusal nobody can read is worse than none.
	case CloneRunFinishedMsg:
		return m.handleCloneRunFinished()

	case jobs.ChangedMsg:
		return m.handleJobsChanged(msg)

	case components.CreationFormSubmitMsg:
		return m.handleCreationSubmit(msg)

	case components.CreationFormCancelMsg:
		m.mode = ModeNormal
		m.creationForm = nil
		return m, nil

	case TemplatesLoadedMsg:
		return m.handleTemplatesLoaded(msg)

	case GroupCreatedMsg:
		return m.handleGroupCreated(msg)

	case ProjectCreatedMsg:
		return m.handleProjectCreated(msg)

	case components.OptionConfirmModalYesMsg:
		return m.handleDeleteConfirmed(msg.Option)

func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	// Filter bar search mode - prioritaire
	if m.table.InEditMode() {
		return m, m.table.Update(msg)
	}

	// Handle mode-specific input
	switch m.mode {
	case ModeCloning:
		return m.handleCloningKey(msg)
	case ModeSelecting:
		return m.handleSelectingKey(msg)
	case ModeLoadingTemplates:
		// Ignore input while loading templates
		return m, nil
	case ModeCreatingProject:
		if m.creationForm != nil {
			var cmd tea.Cmd
			m.creationForm, cmd = m.creationForm.Update(msg)
			return m, cmd
		}
	case ModeConfirmingDelete:
		if m.deleteConfirmModal != nil {
			var cmd tea.Cmd
			m.deleteConfirmModal, cmd = m.deleteConfirmModal.Update(msg)
			return m, cmd
		}
	}

	// Normal mode. Actions resolve the cursor through the table, which resolves
	// it against the very slice its rows were built from.

