// An unconfigured registry is the common case, and must not be treated as a
// failure: the form opens with no templates and no warning.
func TestLoadTemplatesWithoutARegistryIsSilent(t *testing.T) {
	m := New(testConfig(), &shared.State{})

	msg, ok := testutil.MsgOf[TemplatesLoadedMsg](m.loadTemplates())

	if !ok {
		t.Fatal("loadTemplates() produced no TemplatesLoadedMsg")
	}
	if msg.Error != nil || len(msg.Templates) != 0 {
		t.Errorf("an unconfigured registry produced error=%v templates=%v", msg.Error, msg.Templates)
	}
}

func TestLoadTemplatesReportsARegistryFailure(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
	}))
	defer server.Close()

	cfg := testConfig()
	cfg.Registry.URL = server.URL
	cfg.Registry.TemplatesRepository = "templates"
	m := New(cfg, &shared.State{})

	msg, _ := testutil.MsgOf[TemplatesLoadedMsg](m.loadTemplates())

	if msg.Error == nil {
		t.Error("a failing registry produced no error")
	}
}

// Pagination went with the listing: it is the backend's, and D34's tests live
// in internal/forge/gitlab (§3.6 step 3). The paged fake that served it here
// went with them.

// The clone reads a path and a type. It used to pay two extra requests per
// project for a CI badge and a role it never looks at — on two hundred
// repositories, 400 calls for nothing.
func TestDiscoveryDoesNotDecorateTheProjectsItFinds(t *testing.T) {
	f := newFakeGitLab(t, map[string]string{
		"/api/v4/groups/1/subgroups":    `[]`,
		"/api/v4/groups/1/projects":     oneProjectJSON,
		"/api/v4/projects/11/pipelines": pipelineJSON,
		"/api/v4/projects/11/members":   memberJSON,
	})
	m := serverModel(t, f)

	children, err := discoverChildren(context.Background(), m.shared.Forge, &TreeNode{ID: "1", FullPath: "infra"}, true)
	if err != nil {
		t.Fatalf("discoverChildren() error = %v", err)
	}
	if len(children) != 1 {
		t.Fatalf("found %d children, want the project", len(children))
	}

	m = feed(t, m, testutil.Key(keymap.Clone))

	if m.mode != ModeNormal {
		t.Error("C started a clone selection while the search box had focus")
	}
	if !strings.Contains(m.table.FilterBar().SearchQuery(), keymap.Clone) {
		t.Errorf("C did not reach the search box; query = %q", m.table.FilterBar().SearchQuery())
	}
}

// ── Create ───────────────────────────────────────────────────────────────────

// ctrl+n parents the new resource on the group being browsed, not on the
// highlighted row — creating inside a group you are looking at is the common
// case, and the highlighted row may be a project.
func TestCreateParentsOnTheBrowsedGroup(t *testing.T) {
	m := feed(t, loadedModel(t), testutil.Key(keymap.New))
	if m.creationParentID != "" || m.creationParentName != "" {
		t.Errorf("at the root, parent = (%q, %q), want none", m.creationParentID, m.creationParentName)
	}
	if m.mode != ModeLoadingTemplates {
		t.Errorf("mode = %v after ctrl+n, want ModeLoadingTemplates", m.mode)
	}

	m = feed(t, drilledModel(t), testutil.Key("down"), testutil.Key(keymap.New))
	if m.creationParentID != "1" || m.creationParentName != "alpha" {
		t.Errorf("inside alpha, parent = (%q, %q), want alpha regardless of the cursor", m.creationParentID, m.creationParentName)
	}
}

func TestTemplatesLoadedOpensTheForm(t *testing.T) {
	m := feed(t, loadedModel(t), testutil.Key(keymap.New))

	m = feed(t, m, TemplatesLoadedMsg{Templates: []oci.TemplateEntry{
		{Name: "go-service", Repository: "templates/go", Tag: "v1"},
	}})

	if m.mode != ModeCreatingProject {
		t.Errorf("mode = %v once the templates arrived, want ModeCreatingProject", m.mode)
	}
	if m.creationForm == nil {
		t.Fatal("no creation form after the templates arrived")
	}
	if len(m.templateEntries) != 1 {
		t.Errorf("templateEntries = %v, want the one that arrived", m.templateEntries)
	}
}

// D71: a project or subgroup cannot be more open than the group it goes into,
// so the form offers only what "alpha" (private) allows and says why.
func TestVisibilityIsLimitedByAPrivateParent(t *testing.T) {
	m := feed(t, drilledModel(t), testutil.Key(keymap.New), TemplatesLoadedMsg{})

	// Onto the Visibility field: Type -> Name -> Desc -> Visibility.
	m = feed(t, m, testutil.Keys("down", "down", "down")...)
	view := m.creationForm.View()
	if !strings.Contains(view, "limited by the parent group's visibility (private)") {
		t.Errorf("the form under a private group does not say so:\n%s", view)
	}

	m = feed(t, m, testutil.Key("right"))
	if view := m.creationForm.View(); !strings.Contains(view, "private") || strings.Contains(view, "internal") {
		t.Errorf("→ moved past the only choice a private parent allows:\n%s", view)
	}
}

