		scannedDir = dir
		_, err := os.Stat(filepath.Join(dir, "app.env"))
		sawFile = err == nil
		return &scan.Result{Counts: scan.SeverityCounts{Critical: 1, High: 2}, EndTime: time.Now()}, nil
	})
